const cfg = $('Set Approval Policy').first().json;
const b = $input.first().json.body || {};
const errors = [];
let rates = {}; try { rates = JSON.parse(cfg.currencyRates); } catch (e) {}

const requesterEmail = String(b.requesterEmail || '').trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(requesterEmail)) errors.push('requesterEmail must be a valid email');
const department = String(b.department || '').trim().toLowerCase();
if (!/^[a-z0-9_ -]{1,64}$/.test(department)) errors.push('department is required');
const vendorId = String(b.vendorId || '').trim();
if (!/^[A-Za-z0-9_-]{1,64}$/.test(vendorId)) errors.push('vendorId is required (letters, numbers, - and _)');
const amount = Number(b.amount);
if (!Number.isFinite(amount) || amount <= 0 || amount > 1e9) errors.push('amount must be a positive number');
const currency = String(b.currency || 'USD').toUpperCase();
if (!(currency in rates)) errors.push('currency must be one of ' + Object.keys(rates).join(', '));
const description = String(b.description || '').trim();
if (description.length < 5 || description.length > 500) errors.push('description must be 5-500 characters');

const requestId = 'PR-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const amountUsd = errors.length ? 0 : Math.round(amount * rates[currency] * 100) / 100;
return [{ json: { valid: errors.length === 0, errors, requestId, requesterEmail, department, vendorId, amount, currency, amountUsd, description } }];

const cfg = $('Set Approval Policy').first().json;
const req = $('Code - Validate & Normalize Request').first().json;
const row = $input.first().json || {};
const tiers = JSON.parse(cfg.spendTiers), approvers = JSON.parse(cfg.approvers);
const ORDER = ['manager', 'procurement', 'security', 'finance', 'cfo'];
const reasons = [], flags = [], levels = new Set();
let reject = null;
const stop = msg => { if (!reject) reject = msg; };

// Department rules
const budget = Number(row.annual_budget) || 0, used = (Number(row.spent) || 0) + (Number(row.committed) || 0);
const remaining = budget - used;
if (!row.department) stop('unknown department "' + req.department + '"');
else if (row.budget_status === 'frozen') stop('department budget is frozen');

// Vendor risk rules
let risk = row.risk_level || 'unknown';
if (!row.vendor_id) { flags.push('unknown_vendor'); levels.add('procurement'); levels.add('security'); }
else if (risk === 'blocked') stop('vendor blocked' + (row.blocked_reason ? ': ' + row.blocked_reason : ''));
else {
  if (!row.approved) { flags.push('vendor_not_approved'); levels.add('procurement'); }
  if (risk === 'high') { flags.push('high_risk_vendor'); levels.add('procurement'); if (cfg.requireSecurityForHighRisk) levels.add('security'); }
  if (risk === 'medium' && req.amountUsd > Number(cfg.procurementReviewOverUsd)) { flags.push('medium_risk_over_review_limit'); levels.add('procurement'); }
}

// Spend limit tier, counting what was already bought from this vendor by this department in 30 days (anti order-splitting)
const recent = Number(row.recent_vendor_spend) || 0;
const effective = req.amountUsd + recent;
const tierOf = x => tiers.find(t => t.upToUsd === null || x <= Number(t.upToUsd));
const tier = tierOf(effective);
if (recent > 0 && tierOf(effective) !== tierOf(req.amountUsd)) flags.push('cumulative_vendor_spend');
tier.levels.forEach(l => levels.add(l));
if (req.amountUsd > Number(cfg.maxRequestUsd)) stop('amount exceeds the maximum of ' + cfg.maxRequestUsd + ' USD, needs a board decision');
if (row.department && req.amountUsd > remaining) { flags.push('over_budget'); levels.add('finance'); }

// Nobody approves their own purchase
if (row.manager_email && String(row.manager_email).toLowerCase() === req.requesterEmail && levels.has('manager')) {
  levels.delete('manager'); levels.add('finance'); flags.push('self_approval_avoided');
}

const ordered = ORDER.filter(l => levels.has(l)).map(l => {
  const em = l === 'manager' ? row.manager_email : approvers[l];
  if (!em) flags.push('missing_approver_' + l);
  return { level: l, email: em || approvers.finance };
});
const approvedVendor = !!row.vendor_id && !!row.approved;
let decision = reject ? 'reject' : (ordered.length === 0 && approvedVendor && ['low', 'medium'].includes(risk)) ? 'auto_approve' : 'needs_approval';
if (decision === 'needs_approval' && !ordered.length) ordered.push({ level: 'finance', email: approvers.finance });

if (reject) reasons.push(reject);
else if (decision === 'auto_approve') reasons.push('within auto-approval limit for a ' + risk + '-risk approved vendor');
else reasons.push('requires ' + ordered.map(o => o.level).join(' > ') + ' approval');
if (flags.length) reasons.push('flags: ' + flags.join(', '));

return [{ json: { ...req, decision, riskLevel: risk, reasons, flags, levels: ordered, effectiveUsd: effective, remainingBudget: row.department ? remaining : null,
  vendorName: row.vendor_name || req.vendorId, managerEmail: row.manager_email || null } }];

