INSERT INTO pa_requests (request_id, requester_email, department, vendor_id, vendor_name, amount, currency, amount_usd, description, status, risk_level, required_levels, flags)
VALUES ($1::text, $2::text, $3::text, $4::text, $5::text, $6::numeric, $7::text, $8::numeric, $9::text, 'pending', $10::text, $11::jsonb, $12::jsonb)
RETURNING request_id;

