const ev = $('Code - Evaluate Approval Policy').first().json;
const f = $input.first().json || {};
const status = f.status || 'already_finalized';
const label = { approved: 'APPROVED', rejected: 'REJECTED', expired: 'EXPIRED' }[status] || status.toUpperCase();
const money = ev.currency + ' ' + Number(ev.amount).toLocaleString('en-US');
const html = '<p>Your purchase request <b>' + ev.requestId + '</b> (' + money + ' with ' + ev.vendorName + ') was <b>' + label + '</b>.</p>' +
  (f.po_number ? '<p>Purchase order number: <b>' + f.po_number + '</b></p>' : '') +
  '<p>Reason: ' + String(f.final_reason || '').replace(/</g, '&lt;') + '</p>';
const icon = status === 'approved' ? ':white_check_mark:' : ':no_entry:';
const text = icon + ' Purchase ' + ev.requestId + ' ' + label + ': ' + money + ' to ' + ev.vendorName + ' (' + ev.department + ', ' + ev.riskLevel + ' risk vendor)' + (f.po_number ? ' | ' + f.po_number : '') + ' | ' + (f.final_reason || '');
return [{ json: { to: ev.requesterEmail, subject: 'Purchase request ' + ev.requestId + ': ' + label, html, slackText: text } }];

const ev = $('Code - Evaluate Approval Policy').first().json;
const cfg = $('Set Approval Policy').first().json;
// First pass starts at level 0; later passes continue from the state left by "Code - Process Decision"
const prev = $('Code - Process Decision').isExecuted ? $('Code - Process Decision').first().json : {};
const levelIndex = Number(prev.levelIndex) || 0, reminders = Number(prev.reminders) || 0;
const step = ev.levels[levelIndex];
const token = Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 10);
const base = $execution.resumeUrl, sep = base.includes('?') ? '&' : '?';
const link = d => base + sep + 'decision=' + d + '&token=' + token;
const money = ev.currency + ' ' + Number(ev.amount).toLocaleString('en-US');
const rows = [['Request', ev.requestId], ['Requester', ev.requesterEmail], ['Department', ev.department], ['Vendor', ev.vendorName + ' (' + ev.riskLevel + ' risk)'],
  ['Amount', money + (ev.currency !== 'USD' ? ' (~USD ' + ev.amountUsd + ')' : '')], ['Description', ev.description], ['Your level', step.level + ' (' + (levelIndex + 1) + ' of ' + ev.levels.length + ')'],
  ['Why approval is needed', ev.reasons.join('; ')]];
const html = '<p>' + (reminders ? '<b>Reminder ' + reminders + ':</b> ' : '') + 'A purchase request needs your decision.</p><table cellpadding="4">' +
  rows.map(r => '<tr><td><b>' + r[0] + '</b></td><td>' + String(r[1]).replace(/</g, '&lt;') + '</td></tr>').join('') + '</table>' +
  '<p><a href="' + link('approve') + '">Approve</a> &nbsp;|&nbsp; <a href="' + link('reject') + '">Reject</a></p>' +
  '<p>If there is no answer in ' + cfg.reminderHours + 'h you will be reminded (up to ' + cfg.maxReminders + ' times), then the request expires.</p>';
return [{ json: { levelIndex, reminders, level: step.level, approverEmail: step.email, token,
  emailSubject: (reminders ? 'Reminder: ' : '') + 'Approval needed: ' + money + ' for ' + ev.vendorName + ' (' + ev.requestId + ')', emailHtml: html } }];

const step = $('Code - Build Approval Step').first().json;
const ev = $('Code - Evaluate Approval Policy').first().json;
const cfg = $('Set Approval Policy').first().json;
const w = $input.first().json || {};
const q = w.query || {};
const out = { requestId: ev.requestId, level: step.level, approver: step.approverEmail, levelIndex: step.levelIndex, reminders: step.reminders, comment: String(q.comment || '').slice(0, 300) };

if (!q.decision) {                                   // wait timed out: remind, then expire
  const reminders = step.reminders + 1;
  if (reminders > Number(cfg.maxReminders)) return [{ json: { ...out, route: 'rejected', finalStatus: 'expired', decidedBy: 'system', reason: 'no decision from ' + step.level + ' after ' + cfg.maxReminders + ' reminders', auditEvent: 'expired', auditDetail: step.level } }];
  return [{ json: { ...out, route: 'continue', reminders, auditEvent: 'reminder', auditDetail: 'reminder ' + reminders + ' to ' + step.approverEmail } }];
}
if (q.token !== step.token) return [{ json: { ...out, route: 'continue', auditEvent: 'invalid_token', auditDetail: 'decision link did not match, waiting again' } }];
if (q.decision === 'approve') {
  const next = step.levelIndex + 1;
  if (next >= ev.levels.length) return [{ json: { ...out, route: 'approved', finalStatus: 'approved', decidedBy: step.approverEmail, reason: 'approved by ' + ev.levels.map(l => l.level).join(' > '), auditEvent: 'approved', auditDetail: step.level + ' approved (final)' } }];
  return [{ json: { ...out, route: 'continue', levelIndex: next, reminders: 0, auditEvent: 'approved', auditDetail: step.level + ' approved, moving to ' + ev.levels[next].level } }];
}
return [{ json: { ...out, route: 'rejected', finalStatus: 'rejected', decidedBy: step.approverEmail, reason: step.level + ' rejected' + (out.comment ? ': ' + out.comment : ''), auditEvent: 'rejected', auditDetail: out.comment || step.level } }];
